import { createAdminSupabaseClient } from '../../../lib/supabase-admin'
import { resolveIdentifier, hashResetCode } from '../../../lib/auth-identifier'
import { NextResponse } from 'next/server'

// Public, unauthenticated — this IS the "I'm locked out" recovery path.
// The code was generated by an admin (see /admin/users) and relayed to
// the user out of band; this is where they redeem it for a password they
// pick themselves.
export async function POST(request: Request) {
  const { identifier, code, newPassword } = await request.json()

  if (!identifier || !code || !newPassword) {
    return NextResponse.json({ error: 'Fill in every field' }, { status: 400 })
  }
  if (newPassword.length < 4) {
    return NextResponse.json({ error: 'Password must be at least 4 characters' }, { status: 400 })
  }

  const genericError = NextResponse.json({ error: 'That code is invalid or has expired — ask the admin for a new one' }, { status: 400 })

  const supabaseAdmin = createAdminSupabaseClient()
  const resolved = await resolveIdentifier(supabaseAdmin, identifier)
  if (!resolved) return genericError

  const codeHash = hashResetCode(code)
  const { data: matches } = await supabaseAdmin
    .from('password_reset_codes')
    .select('id')
    .eq('user_id', resolved.userId)
    .eq('code_hash', codeHash)
    .is('used_at', null)
    .gt('expires_at', new Date().toISOString())
    .limit(1)

  if (!matches || matches.length === 0) return genericError

  const { error: updateError } = await supabaseAdmin.auth.admin.updateUserById(resolved.userId, { password: newPassword })
  if (updateError) {
    return NextResponse.json({ error: updateError.message }, { status: 500 })
  }

  await supabaseAdmin.from('password_reset_codes').update({ used_at: new Date().toISOString() }).eq('id', matches[0].id)

  return NextResponse.json({ success: true })
}
